SourceCode.Declaration:
/// <summary>
/// Denotes a set of competing lines.
/// That is, lines from same component code (Trade Agreement, Margin Code, etc.), 
/// with identical header attribute group, line attribute group and attribute priority structures.
/// </summary>
internal abstract class GUPPriceEngineAbstractLineAggregation
{

    // All lines (of the component code) within the aggregation object.
    Set lineRecIdSet;

    // For same component code, same combination will have same [attribute group priority].
    int linePriority = 0;

    str attributeGroupKey = null;


}

Method.Source:
public void new()
{
    this.lineRecIdSet = new Set(Types::Int64);
}

/// <summary>
/// Used when attributeGroupKey is same, to avoid hash collision.
/// </summary>
/// <param name = "_newLine">Another line to compare.</param>
/// <returns>True if two lines are compete.</returns>
public abstract boolean canAddAsCompeteLine(GUPPriceEngineAbstractLine _newLine)
{
}
